"""Sinh p3data.js (thuật ngữ EN–VI) từ tools/gloss.py. Chạy: python tools/build_p3.py"""
import json, os, sys
H = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, H)
from gloss import G
rows = [{"en": a, "vi": b, "ex": c, "d": d} for a, b, c, d in G]
open(os.path.join(H, "..", "p3data.js"), "w", encoding="utf8").write(
    "/* generated by tools/build_p3.py — do not edit by hand */\nwindow.V10GLOSS=" + json.dumps(rows, ensure_ascii=False) + ";\n")
print(len(rows), "terms", {d: sum(r["d"] == d for r in rows) for d in sorted({r["d"] for r in rows})})
